        static float F(string h) => BitConverter.Int32BitsToSingle(Convert.ToInt32(h, 16));
        static Vector3 V3(string s) { var p = s.Split(','); return new Vector3(F(p[0]), F(p[1]), F(p[2])); }
        static Quaternion Q(string s) { var p = s.Split(','); return new Quaternion(F(p[0]), F(p[1]), F(p[2]), F(p[3])); }
        static string Hex(float f) => BitConverter.SingleToInt32Bits(f).ToString("x8");
        static string Hex(Vector3 v) => Hex(v.x) + "," + Hex(v.y) + "," + Hex(v.z);

        static Transform Build(string levels, out Transform root)
        {
            Transform parent = null;
            root = null;
            foreach (var level in levels.Split(' '))
            {
                var f = level.Split(';');
                var t = new GameObject("level").transform;
                root ??= t;
                if (parent != null) t.SetParent(parent, false);
                t.localPosition = V3(f[0]);
                t.localRotation = Q(f[1]);
                t.localScale = V3(f[2]);
                parent = t;
            }
            return parent;
        }

        [Fact]
        public void PositionSetterMatchesTheOriginalBitForBit()
        {
            foreach (var c in Cases)
            {
                var f = c.Split('|');
                var parent = Build(f[0], out var root);
                var child = new GameObject("child").transform;
                child.SetParent(parent, false);
                child.position = V3(f[1]);
                Assert.Equal(f[2], Hex(child.localPosition));
                UnityEngine.Object.DestroyImmediate(root.gameObject);
            }
        }

        [Fact]
        public void InverseTransformPointMatchesTheOriginalBitForBit()
        {
            foreach (var c in Cases)
            {
                var f = c.Split('|');
                var parent = Build(f[0], out var root);
                Assert.Equal(f[2], Hex(parent.InverseTransformPoint(V3(f[1]))));
                UnityEngine.Object.DestroyImmediate(root.gameObject);
            }
        }

        /// A rotated level anywhere in the chain keeps the matrix products: the
        /// worldToLocalMatrix for InverseTransformPoint, the inverted world matrix for the setter.
        [Fact]
        public void RotatedChainsKeepTheMatrixProducts()
        {
            var root = new GameObject("root").transform;
            root.localPosition = new Vector3(640f, 360f, 0f);
            root.localScale = new Vector3(0.86f, 0.86f, 0.86f);
            var mid = new GameObject("mid").transform;
            mid.SetParent(root, false);
            mid.localPosition = new Vector3(-12.5f, 3.25f, 0f);
            mid.localRotation = Quaternion.Euler(0f, 0f, 30f);
            var leaf = new GameObject("leaf").transform;
            leaf.SetParent(mid, false);
            leaf.localPosition = new Vector3(7f, -1f, 0f);
            var point = new Vector3(41.28003f, 17.5f, 0f);
            Assert.Equal(Hex(leaf.worldToLocalMatrix.MultiplyPoint3x4(point)), Hex(leaf.InverseTransformPoint(point)));
            var child = new GameObject("child").transform;
            child.SetParent(leaf, false);
            child.position = point;
            Assert.Equal(Hex(leaf.localToWorldMatrix.inverse.MultiplyPoint3x4(point)), Hex(child.localPosition));
            UnityEngine.Object.DestroyImmediate(root.gameObject);
        }
